"""
Port interfaces (abstract contracts) for the runtime profile adapter layer.

All five infrastructure concerns are defined here as runtime-checkable Protocols.
Business logic must depend only on these port interfaces, never on concrete
adapter classes.
"""

from __future__ import annotations

from typing import Any, Protocol, runtime_checkable


@runtime_checkable
class ObjectStoragePort(Protocol):
    """Port for object/blob storage operations."""

    def put_object(self, bucket: str, key: str, data: bytes) -> None: ...
    def get_object(self, bucket: str, key: str) -> bytes: ...
    def delete_object(self, bucket: str, key: str) -> None: ...
    def object_exists(self, bucket: str, key: str) -> bool: ...
    def ensure_bucket(self, bucket: str) -> None: ...


@runtime_checkable
class QueuePort(Protocol):
    """Port for message queue operations."""

    def send_message(self, queue_name: str, body: str, attributes: dict[str, str] | None = None) -> str: ...
    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]: ...
    def delete_message(self, queue_name: str, receipt_handle: str) -> None: ...
    def ensure_queue(self, queue_name: str) -> str: ...


@runtime_checkable
class EventingPort(Protocol):
    """Port for event/notification publishing."""

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str: ...
    def ensure_topic(self, topic: str) -> str: ...


@runtime_checkable
class SecretsPort(Protocol):
    """Port for secrets retrieval."""

    def get_secret(self, secret_id: str) -> str: ...
    def put_secret(self, secret_id: str, value: str) -> None: ...


@runtime_checkable
class LogSinkPort(Protocol):
    """Port for structured log sink operations."""

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None: ...
    def ensure_log_group(self, log_group: str) -> None: ...
