"""
Object storage adapters for AWS (S3 via boto3) and on-prem (MinIO).
"""

from __future__ import annotations

import io
import os
from typing import Any

from feature.ports import ObjectStoragePort


class AwsObjectStorageAdapter:
    """AWS S3 object storage adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("s3", **kwargs)

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._client.put_object(Bucket=bucket, Key=key, Body=data)

    def get_object(self, bucket: str, key: str) -> bytes:
        response = self._client.get_object(Bucket=bucket, Key=key)
        return response["Body"].read()

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def object_exists(self, bucket: str, key: str) -> bool:
        from botocore.exceptions import ClientError
        try:
            self._client.head_object(Bucket=bucket, Key=key)
            return True
        except ClientError:
            return False

    def ensure_bucket(self, bucket: str) -> None:
        from botocore.exceptions import ClientError
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            self._client.create_bucket(Bucket=bucket)


class OnpremObjectStorageAdapter:
    """On-prem object storage adapter backed by MinIO (S3-compatible API)."""

    def __init__(
        self,
        endpoint_url: str | None = None,
        access_key: str | None = None,
        secret_key: str | None = None,
    ) -> None:
        from minio import Minio
        from urllib.parse import urlparse

        endpoint_url = endpoint_url or os.environ.get("MINIO_ENDPOINT", "http://localhost:9000")
        access_key = access_key or os.environ.get("MINIO_ACCESS_KEY", "minioadmin")
        secret_key = secret_key or os.environ.get("MINIO_SECRET_KEY", "minioadmin")

        parsed = urlparse(endpoint_url)
        host = parsed.netloc or parsed.path
        secure = parsed.scheme == "https"

        self._client = Minio(
            host,
            access_key=access_key,
            secret_key=secret_key,
            secure=secure,
        )

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._client.put_object(bucket, key, io.BytesIO(data), length=len(data))

    def get_object(self, bucket: str, key: str) -> bytes:
        response = self._client.get_object(bucket, key)
        try:
            return response.read()
        finally:
            response.close()
            response.release_conn()

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.remove_object(bucket, key)

    def object_exists(self, bucket: str, key: str) -> bool:
        try:
            self._client.stat_object(bucket, key)
            return True
        except Exception:
            return False

    def ensure_bucket(self, bucket: str) -> None:
        if not self._client.bucket_exists(bucket):
            self._client.make_bucket(bucket)
