"""
Eventing adapters for AWS (SNS via boto3) and on-prem (Redis Pub/Sub).
"""

from __future__ import annotations

import json
import os
import uuid
from typing import Any

from feature.ports import EventingPort


class AwsEventingAdapter:
    """AWS SNS eventing adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("sns", **kwargs)
        self._topic_arn_cache: dict[str, str] = {}

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str:
        arn = self._topic_arn_cache.get(topic)
        if not arn:
            arn = self.ensure_topic(topic)
        kwargs: dict[str, Any] = {"TopicArn": arn, "Message": message}
        if attributes:
            kwargs["MessageAttributes"] = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.publish(**kwargs)
        return resp["MessageId"]

    def ensure_topic(self, topic: str) -> str:
        resp = self._client.create_topic(Name=topic)
        arn = resp["TopicArn"]
        self._topic_arn_cache[topic] = arn
        return arn


class OnpremEventingAdapter:
    """On-prem eventing adapter backed by Redis Pub/Sub."""

    def __init__(self, redis_url: str | None = None) -> None:
        import redis as redis_lib
        redis_url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._client = redis_lib.Redis.from_url(redis_url, decode_responses=True)

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str:
        msg_id = str(uuid.uuid4())
        envelope = json.dumps({"MessageId": msg_id, "Message": message, "Attributes": attributes or {}})
        self._client.publish(topic, envelope)
        return msg_id

    def ensure_topic(self, topic: str) -> str:
        # Redis Pub/Sub topics are implicit.
