"""
Secrets adapters for AWS (Secrets Manager via boto3) and on-prem (env vars / JSON file).
"""

from __future__ import annotations

import json
import os
from typing import Any

from feature.ports import SecretsPort


class AwsSecretsAdapter:
    """AWS Secrets Manager adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("secretsmanager", **kwargs)

    def get_secret(self, secret_id: str) -> str:
        resp = self._client.get_secret_value(SecretId=secret_id)
        return resp["SecretString"]

    def put_secret(self, secret_id: str, value: str) -> None:
        from botocore.exceptions import ClientError
        try:
            self._client.create_secret(Name=secret_id, SecretString=value)
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "ResourceExistsException":
                self._client.put_secret_value(SecretId=secret_id, SecretString=value)
            else:
                raise


class OnpremSecretsAdapter:
    """On-prem secrets adapter backed by environment variables or a local JSON file."""

    def __init__(self, secrets_file: str | None = None) -> None:
        self._secrets_file = secrets_file or os.environ.get("SECRETS_FILE", "")
        self._store: dict[str, str] = {}
        if self._secrets_file and os.path.isfile(self._secrets_file):
            with open(self._secrets_file, "r") as f:
                self._store = json.load(f)

    def get_secret(self, secret_id: str) -> str:
        val = os.environ.get(secret_id)
        if val is not None:
            return val
        if secret_id in self._store:
            return self._store[secret_id]
        raise KeyError(f"Secret '{secret_id}' not found in environment or secrets file.")

    def put_secret(self, secret_id: str, value: str) -> None:
        self._store[secret_id] = value
        if self._secrets_file:
            with open(self._secrets_file, "w") as f:
                json.dump(self._store, f)
