"""
Log sink adapters for AWS (CloudWatch Logs via boto3) and on-prem (local JSONL files).
"""

from __future__ import annotations

import json
import os
import time
from typing import Any

from feature.ports import LogSinkPort


class AwsLogSinkAdapter:
    """AWS CloudWatch Logs adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("logs", **kwargs)

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None:
        from botocore.exceptions import ClientError
        try:
            self._client.create_log_stream(logGroupName=log_group, logStreamName=log_stream)
        except ClientError as exc:
            if exc.response["Error"]["Code"] != "ResourceAlreadyExistsException":
                raise
        log_events = [
            {"timestamp": int(time.time() * 1000), "message": json.dumps(e) if isinstance(e, dict) else str(e)}
            for e in events
        ]
        self._client.put_log_events(
            logGroupName=log_group,
            logStreamName=log_stream,
            logEvents=log_events,
        )

    def ensure_log_group(self, log_group: str) -> None:
        from botocore.exceptions import ClientError
        try:
            self._client.create_log_group(logGroupName=log_group)
        except ClientError as exc:
            if exc.response["Error"]["Code"] != "ResourceAlreadyExistsException":
                raise


class OnpremLogSinkAdapter:
    """On-prem log sink adapter that writes structured logs to local JSONL files."""

    def __init__(self, log_dir: str | None = None) -> None:
        self._log_dir = log_dir or os.environ.get("LOG_SINK_DIR", "/tmp/logs")
        os.makedirs(self._log_dir, exist_ok=True)

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None:
        group_dir = os.path.join(self._log_dir, log_group)
        os.makedirs(group_dir, exist_ok=True)
        filepath = os.path.join(group_dir, f"{log_stream}.jsonl")
        with open(filepath, "a") as f:
            for event in events:
                record = {"timestamp": time.time(), "event": event}
                f.write(json.dumps(record) + "\n")

    def ensure_log_group(self, log_group: str) -> None:
        group_dir = os.path.join(self._log_dir, log_group)
        os.makedirs(group_dir, exist_ok=True)
