"""
Profile-aware adapter registry builder and parity validator.

The registry is the single entry point for adapter construction.
Business code calls build_adapter_registry() once at startup and passes
the registry (or individual ports) via dependency injection.
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from feature.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)


# ---------------------------------------------------------------------------
# Deployment profile
# ---------------------------------------------------------------------------

class DeploymentProfile(str, Enum):
    AWS = "aws"
    ONPREM = "onprem"


def get_deployment_profile() -> DeploymentProfile:
    """Read DEPLOYMENT_PROFILE from environment. Defaults to 'onprem'."""
    raw = os.environ.get("DEPLOYMENT_PROFILE", "onprem").strip().lower()
    try:
        return DeploymentProfile(raw)
    except ValueError:
        raise ValueError(
            f"Invalid DEPLOYMENT_PROFILE='{raw}'. "
            f"Allowed values: {[p.value for p in DeploymentProfile]}"
        )


# ---------------------------------------------------------------------------
# Adapter config
# ---------------------------------------------------------------------------

@dataclass
class AdapterConfig:
    """Optional overrides for adapter construction."""
    # AWS / LocalStack
    aws_endpoint_url: str | None = field(default=None)
    aws_region: str = field(default="us-east-1")
    # MinIO
    minio_endpoint: str | None = field(default=None)
    minio_access_key: str | None = field(default=None)
    minio_secret_key: str | None = field(default=None)
    # Redis
    redis_url: str | None = field(default=None)
    # Secrets file
    secrets_file: str | None = field(default=None)
    # Log dir
    log_dir: str | None = field(default=None)


# ---------------------------------------------------------------------------
# Adapter registry
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class AdapterRegistry:
    """
    Immutable registry of profile-selected adapters.

    Importable as shared.adapters by downstream REQs.
    Business logic depends only on port interfaces, never on this registry's
    concrete adapter types.
    """
    object_storage: ObjectStoragePort
    queue: QueuePort
    eventing: EventingPort
    secrets: SecretsPort
    log_sink: LogSinkPort
    profile: DeploymentProfile


# ---------------------------------------------------------------------------
# Builders
# ---------------------------------------------------------------------------

def _build_aws_registry(config: AdapterConfig) -> AdapterRegistry:
    from feature.object_storage import AwsObjectStorageAdapter
    from feature.queue import AwsQueueAdapter
    from feature.eventing import AwsEventingAdapter
    from feature.secrets import AwsSecretsAdapter
    from feature.log_sink import AwsLogSinkAdapter

    endpoint = config.aws_endpoint_url or os.environ.get("AWS_ENDPOINT_URL")
    region = config.aws_region or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
    return AdapterRegistry(
        object_storage=AwsObjectStorageAdapter(endpoint_url=endpoint, region_name=region),
        queue=AwsQueueAdapter(endpoint_url=endpoint, region_name=region),
        eventing=AwsEventingAdapter(endpoint_url=endpoint, region_name=region),
        secrets=AwsSecretsAdapter(endpoint_url=endpoint, region_name=region),
        log_sink=AwsLogSinkAdapter(endpoint_url=endpoint, region_name=region),
        profile=DeploymentProfile.AWS,
    )


def _build_onprem_registry(config: AdapterConfig) -> AdapterRegistry:
    from feature.object_storage import OnpremObjectStorageAdapter
    from feature.queue import OnpremQueueAdapter
    from feature.eventing import OnpremEventingAdapter
    from feature.secrets import OnpremSecretsAdapter
    from feature.log_sink import OnpremLogSinkAdapter

    return AdapterRegistry(
        object_storage=OnpremObjectStorageAdapter(
            endpoint_url=config.minio_endpoint,
            access_key=config.minio_access_key,
            secret_key=config.minio_secret_key,
        ),
        queue=OnpremQueueAdapter(redis_url=config.redis_url),
        eventing=OnpremEventingAdapter(redis_url=config.redis_url),
        secrets=OnpremSecretsAdapter(secrets_file=config.secrets_file),
        log_sink=OnpremLogSinkAdapter(log_dir=config.log_dir),
        profile=DeploymentProfile.ONPREM,
    )


_BUILDERS: dict[DeploymentProfile, Any] = {
    DeploymentProfile.AWS: _build_aws_registry,
    DeploymentProfile.ONPREM: _build_onprem_registry,
}


def build_adapter_registry(config: AdapterConfig | None = None) -> AdapterRegistry:
    """
    Build an AdapterRegistry for the current DEPLOYMENT_PROFILE.

    This is the single entry point for adapter construction.
    Business code calls this once at startup and passes the registry
    (or individual ports) via dependency injection.
    """
    profile = get_deployment_profile()
    cfg = config or AdapterConfig()
    builder = _BUILDERS[profile]
    return builder(cfg)


# ---------------------------------------------------------------------------
# Parity validation
# ---------------------------------------------------------------------------

_REQUIRED_PORTS = [
    ("object_storage", ObjectStoragePort),
    ("queue", QueuePort),
    ("eventing", EventingPort),
    ("secrets", SecretsPort),
    ("log_sink", LogSinkPort),
]


def validate_registry_parity(registry: AdapterRegistry) -> list[str]:
    """
    Validate that every adapter in the registry satisfies its port interface.
    Returns a list of violation descriptions (empty means valid).
    """
    violations: list[str] = []
    for attr_name, port_type in _REQUIRED_PORTS:
        adapter = getattr(registry, attr_name, None)
        if adapter is None:
            violations.append(f"Missing adapter for port '{attr_name}'")
        elif not isinstance(adapter, port_type):
            violations.append(
                f"Adapter '{attr_name}' ({type(adapter).__name__}) "
                f"does not satisfy {port_type.__name__}"
            )
    return violations
