        for i in range(3):
            q.send_message(queue_name, f"msg-{i}")

        all_msgs: list[dict] = []
        for _ in range(5):  # poll a few times
            batch = q.receive_messages(queue_name, max_messages=10, wait_seconds=1)
            all_msgs.extend(batch)
            for m in batch:
                q.delete_message(queue_name, m["ReceiptHandle"])
            if len(all_msgs) >= 3:
                break

        bodies = sorted([m["Body"] for m in all_msgs])
        assert bodies == ["msg-0", "msg-1", "msg-2"]


